import{_ as p,a0 as n,w as o,s as u,I as i,x as l,a1 as a,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"使用 FileZilla 以圖形界面連接 SFTP 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 FileZilla 以圖形界面連接 SFTP 服務器 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 FileZilla 以圖形界面連接 SFTP 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 FileZilla 以圖形界面連接 SFTP 服務器 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220307 Using FileZilla for Connecting to SFTP Server Via GUI","title":"使用 FileZilla 以圖形界面連接 SFTP 服務器","tag":"202203","desc":""},"relativePath":"202203/20220307 Using FileZilla for Connecting to SFTP Server Via GUI.md","filePath":"[post].md"}'),f={name:"202203/20220307 Using FileZilla for Connecting to SFTP Server Via GUI.md"};function m(d,t,b,g,T,F){const e=n("Link");return o(),u("div",null,[t[25]||(t[25]=i("h1",{id:"使用-filezilla-以圖形界面連接-sftp-服務器",tabindex:"-1"},[l("使用 FileZilla 以圖形界面連接 SFTP 服務器 "),i("a",{class:"header-anchor",href:"#使用-filezilla-以圖形界面連接-sftp-服務器","aria-label":"Permalink to “使用 FileZilla 以圖形界面連接 SFTP 服務器”"},"​")],-1)),t[26]||(t[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202203/29/164256iljy9w3n053qv28x.jpg",alt:""})],-1)),i("p",null,[t[1]||(t[1]=l("如果你問那些極客系統管理員，他們會肯定的説使用 ",-1)),a(e,{href:"https://linuxhandbook.com/transfer-files-ssh/"},{default:s(()=>[...t[0]||(t[0]=[l("rsync 或者 scp 命令在遠程服務器和本地系統之間傳輸文件",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[27]||(t[27]=i("p",null,"然而，這些都是命令列方式，並不是每個人都能用起來感到舒適。",-1)),t[28]||(t[28]=i("p",null,"謝天謝地的是，有一些圖形化工具能夠讓你從遠程服務器來傳輸文件。",-1)),i("p",null,[a(e,{href:"https://filezilla-project.org/"},{default:s(()=>[...t[3]||(t[3]=[l("FileZilla",-1)])]),_:1}),t[4]||(t[4]=l(" 是一個流行的、跨平台的傳輸文件為目的開源軟件。它支持使用通過 TLS 或者 SSL 加密的 FTP 協議（FTPS），也支持藉助 SSH 的 FTP 協議，以及舊的 FTP 協議。",-1))]),t[29]||(t[29]=r('<p>讓我展示怎樣在 Linux 上安裝 FileZilla 然後用它來文件傳輸。</p><p>那麼，讓我們開始吧！</p><h3 id="在-ubuntu-和其他-linux-發行版上安裝-filezilla" tabindex="-1">在 Ubuntu 和其他 Linux 發行版上安裝 FileZilla <a class="header-anchor" href="#在-ubuntu-和其他-linux-發行版上安裝-filezilla" aria-label="Permalink to “在 Ubuntu 和其他 Linux 發行版上安裝 FileZilla”">​</a></h3><p>你可以使用源碼來安裝，但是還是建議使用你的發行版提供的軟件包。因為它是一個熱門軟件，它應該在許多 Linux 發行版（即便不是全部）的軟件倉庫中可用。請使用你的發行版的軟件中心和包管理器來安裝。</p><p>在 Ubuntu 上，你可以從軟件中心來安裝它：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/filezilla-ubuntu-software-center.png?resize=751%2C382&amp;ssl=1" alt="FileZilla is available in the Ubuntu Software Center"></p><p>你也可以使用命令列的方式來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install filezilla</span></span></code></pre></div>',8)),i("p",null,[t[7]||(t[7]=l("如果你看到 ",-1)),a(e,{href:"https://itsfoss.com/unable-to-locate-package-error-ubuntu/"},{default:s(()=>[...t[5]||(t[5]=[l("軟件包不存在的錯誤",-1)])]),_:1}),t[8]||(t[8]=l("，你應該 ",-1)),a(e,{href:"https://itsfoss.com/ubuntu-repositories/"},{default:s(()=>[...t[6]||(t[6]=[l("開啓 Universe 倉庫",-1)])]),_:1}),t[9]||(t[9]=l("。",-1))]),t[30]||(t[30]=r('<p>一旦安裝成功，打開菜單（通過按 <code>Super</code> 鍵），鍵入 “FileZilla”來啓動它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/filezilla-ubuntu.png?resize=763%2C224&amp;ssl=1" alt="Start FileZilla from the system menu"></p><h3 id="使用-filezilla" tabindex="-1">使用 FileZilla <a class="header-anchor" href="#使用-filezilla" aria-label="Permalink to “使用 FileZilla”">​</a></h3><p>第一次使用 FileZilla 時，你將會看到如下圖所示的一個界面：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/01_filezilla.webp?resize=800%2C431&amp;ssl=1" alt="Screenshot of FileZilla running"></p><p>左邊窗口顯示來自你本地系統的文件和目錄。右邊窗口顯示目前是空的。當你連接到遠程服務器時，來自你的遠程系統的文件會顯示在這裏。</p><p>在我向你展示之前，讓我分享一下關於理解 FileZilla 圖形界面重要方面的一些細節。</p><h4 id="瞭解-filezilla-圖形界面" tabindex="-1">瞭解 FileZilla 圖形界面 <a class="header-anchor" href="#瞭解-filezilla-圖形界面" aria-label="Permalink to “瞭解 FileZilla 圖形界面”">​</a></h4><p>下圖總體上給你展示了 FileZilla 窗口布局的不同部分。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/02_filezilla_layout.webp?resize=800%2C504&amp;ssl=1" alt="FileZilla Window Layout | image credit"></p><p>圖形界面由 6 個不同的區域/窗口來組成。讓我簡短的給你解釋一下：</p><p><strong>1、工具欄</strong>：它有許多選項，如打開站點管理器、刷新本地和遠程目錄文件和文件列表、開始處理當前的文件傳輸隊列、停止正在傳輸的任務並取消隊列中的文件，等等。</p><p><strong>2、快速連接欄</strong>：顧名思義，它允許你快速連接到一個遠程站點，除了主機名、用户名、密碼和端口之外，不需要指定更多細節。</p><p><strong>3、消息日誌</strong>：它顯示了一個日誌，不論你連接成功與否。錯誤消息標記為紅色，正常消息為白色，命令是藍色。</p><p><strong>4 &amp; 5、本地窗口和遠程窗口</strong>：這兩個窗口非常相似，除了本地窗口顯示本地目錄內容，並且有用來上傳文件的上下文菜單；而遠程窗口顯示的是遠程目錄的內容，並有從遠程目錄下載到本地文件的選項。</p><p><strong>6、傳輸隊列</strong>：最後，傳輸隊列窗口顯示正在傳輸的項目的狀態和它們的傳輸速度，以及隊列中的文件和傳輸歷史（僅限當前實例）。</p><h4 id="使用-filezilla-連接到-sftp-服務器" tabindex="-1">使用 FileZilla 連接到 SFTP 服務器 <a class="header-anchor" href="#使用-filezilla-連接到-sftp-服務器" aria-label="Permalink to “使用 FileZilla 連接到 SFTP 服務器”">​</a></h4><p>你需要知道遠程服務器的用户名、密碼和 IP 地址。遠程服務器也應該被設置成能夠接受以這些信息進行的連接。你還需要在目標文件夾有正確的權限設置。</p><p>要新增一個 SFTP 連接，你需要打開站點管理器。有兩種方式可以打開它。</p><p>在菜單欄上的“<ruby>文件<rt>Files</rt></ruby>”菜單選項下有一個“<ruby>站點管理器<rt>Site Manager</rt></ruby>”。或者，你可以直接點擊工具欄上的“站點管理器”圖標。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/03_site_manager_annotated.webp?resize=386%2C170&amp;ssl=1" alt="the Site Manager button on the toolbar"></p><p>一旦站點管理器對話框彈出，點擊“<ruby>新站點<rt>New site</rt></ruby>”按鈕，並（可選地）重命名添加到條目中的新站點。我叫我的站點為“test8”。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/04_site_manager.webp?resize=800%2C577&amp;ssl=1" alt="screenshot of the Site Manager"></p><p>在右側的“<ruby>常規<rt>General</rt></ruby>”標籤下，確保所使用的協議與服務器管理員為你設置的相一致。在我的例子中，我設置了一個 SFTP 服務器（<ruby>藉助 SSH 通道的 FTP<rt>FTP over SSH</rt></ruby>），因此我選擇了“<ruby>SFTP - SSH 文件傳輸協議<rt>SFTP – SSH File Transfer Protocol</rt></ruby>”。</p><p>下一個字段填寫遠程服務器的 IP 地址。</p><p>如果你沒有設置“<ruby>端口號<rt>Port</rt></ruby>”，FileZilla 將假定要使用的端口號為缺省的 SSH 協議的 22 端口。</p><p>“<ruby>登錄類型<rt>Logon Type</rt></ruby>”下拉列表有幾個選項。在“<ruby>常規<rt>Normal</rt></ruby>”登錄方式下，你只需要提供用户名和密碼。</p><p>如果你設置了一對公鑰和私鑰來驗證你的 SSH 用户連接，那麼可以使用“<ruby>密鑰文件授權<rt>Key file authentication</rt></ruby>”方式。</p><p>一旦你為遠程服務器和認證填寫了所有適當的細節，就可以點擊底部的“<ruby>連接<rt>Connect</rt></ruby>”按鈕連接到站點。別擔心，你剛剛建立連接的新站點將會按“登錄類型”保存起來。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/05_successful_connection.webp?resize=800%2C431&amp;ssl=1" alt="Remote pane being populated after a successful connection"></p><p>如果你看到一個 “連接到 &lt;主機 IP 地址&gt;” 的狀態消息，並且最近的狀態消息是 “目錄列表 &quot;/&quot; 顯示成功”，説明你已經成功的連接到了遠程的 SFTP 服務器（使用 SSH 協議的 FTP）。</p><p>另一個 SFTP 連接成功的標誌是，當連接成功建立的時候，遠程目錄窗口有了很多消息。</p><h4 id="發送文件到遠程系統" tabindex="-1">發送文件到遠程系統 <a class="header-anchor" href="#發送文件到遠程系統" aria-label="Permalink to “發送文件到遠程系統”">​</a></h4><p>你必須 <strong>確保你位於要傳輸文件的目錄裏</strong>。傳輸文件非常簡單，只需<strong>雙擊文件</strong>，無需指定指定目標位置。</p><p>如果你在左邊窗口雙擊了一個文件，它立即傳輸到右邊科技的目錄裏（或者有傳輸任務的話，加到隊列中）。</p><p>同樣，從右邊窗口到左邊窗口也是一樣雙擊，即從遠程服務器到本地。<strong>這就是為什麼本地和遠程系統都要在正確的位置是非常重要的原因</strong>。</p><p>此外，你也可以鼠標右擊文件上傳它們（或者加它們到上傳隊列）。目標位置總是 FileZilla 界面中顯示的目錄。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/07_transfer_pane_populated-1.webp?resize=800%2C431&amp;ssl=1" alt="Transfer queue pane showing the local file name, remote destination, transfer speed and an ETA"></p><p>除了方便和快捷方面，這兩種上傳的文件方式沒有什麼不同。</p><h4 id="下載遠程系統中的文件" tabindex="-1">下載遠程系統中的文件 <a class="header-anchor" href="#下載遠程系統中的文件" aria-label="Permalink to “下載遠程系統中的文件”">​</a></h4><p>像上傳文件一樣，當從遠程服務器傳輸文件到本地時也有兩種方式，但不是“上傳”而是“下載”。</p><p>下載的文件將放在本地目錄窗口中，也就是你當前打開的本地窗口。</p><p>你將會注意到除了發送方和接收方不同之外，下載和上傳文件的行為是一樣的。除非連接數受到限制，否則文件傳輸將是並行進行的。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>厲害！有了這些基礎知識，你應該能夠在你的計算機和服務器之間傳輸文件。我希望你能夠學到一些新東西 : )</p><p>如果你感到這些對你有幫助，隨意在評論部分留下你的問題、建議或簡單的一句 “thank you”。</p><hr>',47)),i("p",null,[t[11]||(t[11]=l("via: ",-1)),a(e,{href:"https://itsfoss.com/filezilla-ubuntu/"},{default:s(()=>[...t[10]||(t[10]=[l("https://itsfoss.com/filezilla-ubuntu/",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=l("作者：",-1)),a(e,{href:"https://itsfoss.com/author/pratham/"},{default:s(()=>[...t[12]||(t[12]=[l("Pratham Patel",-1)])]),_:1}),t[17]||(t[17]=l(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[13]||(t[13]=[l("lujun9972",-1)])]),_:1}),t[18]||(t[18]=l(" 譯者：",-1)),a(e,{href:"https://github.com/hwlife"},{default:s(()=>[...t[14]||(t[14]=[l("hwlife",-1)])]),_:1}),t[19]||(t[19]=l(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[15]||(t[15]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[22]||(t[22]=l("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[20]||(t[20]=[l("LCTT",-1)])]),_:1}),t[23]||(t[23]=l(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:s(()=>[...t[21]||(t[21]=[l("Linux中國",-1)])]),_:1}),t[24]||(t[24]=l(" 榮譽推出",-1))])])}const y=p(f,[["render",m]]);export{P as __pageData,y as default};
